  teacher:        ['class:read', 'class:write', 'submission:read', 'submission:grade', 'report:read'],
  student:        ['class:read', 'submission:read', 'submission:write'],
};

// user:     { id, grants: [{ role, scope: { districtId, schoolId?, classId? } }] }
// resource: { type, districtId, schoolId, classId, ownerId? }
function can(user, action, resource) {
  // Checks WHAT the role may do, but not WHERE the role was granted.
  return user.grants.some((g) => (PERMISSIONS[g.role] || []).includes(resource.type + ':' + action));
}

