const PERMISSIONS = {
  district_admin: ['class:read', 'class:write', 'submission:read', 'report:read', 'user:manage'],
  principal:      ['class:read', 'class:write', 'submission:read', 'report:read'],
  teacher:        ['class:read', 'class:write', 'submission:read', 'submission:grade', 'report:read'],
  student:        ['class:read', 'submission:read', 'submission:write'],
};

// A grant's scope covers a resource when every key in the scope matches.
// Fail closed: an empty or missing scope covers nothing.
function covers(scope, resource) {
  const keys = Object.keys(scope || {});
  if (keys.length === 0) return false;
  return keys.every((k) => resource[k] !== undefined && resource[k] === scope[k]);
}

function can(user, action, resource) {
  if (!user || !Array.isArray(user.grants) || !resource) return false;
  const permission = resource.type + ':' + action;
  return user.grants.some((g) => {
    const allowed = PERMISSIONS[g.role];
    if (!allowed || !allowed.includes(permission)) return false;   // 1. what
    if (!covers(g.scope, resource)) return false;                  // 2. where
    if (g.role === 'student' && resource.type === 'submission') {   // 3. whose
      return resource.ownerId === user.id;
    }
    return true;
  });
}

