// District d1 has schools s1 and s2. District d2 is a different customer.
const res = (type, classId, extra = {}) => {
  const map = { c1: ['d1', 's1'], c2: ['d1', 's1'], c3: ['d1', 's2'], c9: ['d2', 's9'] };
  const [districtId, schoolId] = map[classId];
  return { type, districtId, schoolId, classId, ...extra };
};
const msLee = { id: 'u-lee', grants: [{ role: 'teacher', scope: { districtId: 'd1', schoolId: 's1', classId: 'c1' } }] };
const sub = res('submission', 'c1', { ownerId: 'u-ana' });
assertEqual(can(msLee, 'read', sub), true, 'read');
assertEqual(can(msLee, 'grade', sub), true, 'grade');
assertEqual(can(msLee, 'manage', res('user', 'c1')), false, 'teachers cannot manage users');

